import io
import posixpath
from datetime import date, datetime
from decimal import Decimal, ROUND_HALF_UP

def versions(p):
    return sorted(p)

def csv_row(p):
    out=io.StringIO(); csv.writer(out,lineterminator='\n').writerow(p)
    return out.getvalue()[:-1]

def merge(p):
    return {**p['defaults'],**p['overrides']}

