import csv
import io
import posixpath
from datetime import date, datetime
from decimal import Decimal, ROUND_HALF_UP

def page(p):
    start=(p['page']-1)*p['size']
    return p['items'][start:start+p['size']]

def latest(p):
    best={}
    for r in p:
        if r['id'] not in best or r['revision']>best[r['id']]['revision']: best[r['id']]=r
    return [best[k] for k in sorted(best)]

